import{_ as e,o as d,c as r,ak as s}from"./chunks/framework.sV-XtlWr.js";const p=JSON.parse('{"title":"Metrics","description":"Every number the analytics widgets, quality reports, MCP tools and exports show, with its unit, which direction is better and its definition, generated from the metric catalog.","frontmatter":{"title":"Metrics","description":"Every number the analytics widgets, quality reports, MCP tools and exports show, with its unit, which direction is better and its definition, generated from the metric catalog.","lang":"en-US","editLink":false,"head":[["link",{"rel":"canonical","href":"https://piwitests.dev/reference/metrics.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/reference/metrics.html"}],["meta",{"property":"og:title","content":"Metrics | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Every number the analytics widgets, quality reports, MCP tools and exports show, with its unit, which direction is better and its definition, generated from the metric catalog."}]]},"headers":[],"relativePath":"reference/metrics.md","filePath":"reference/metrics.md","lastUpdated":null}'),a={name:"reference/metrics.md"};function n(o,t,i,c,h,l){return d(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="metrics" tabindex="-1">Metrics <a class="header-anchor" href="#metrics" aria-label="Permalink to &quot;Metrics&quot;">​</a></h1><p>The metric catalog: every number the <a href="/reference/analytics-widgets.html">analytics widgets</a>, the <a href="/features/quality-reports.html">quality reports</a>, the <a href="/reference/mcp-tools.html#get_metric_trend">MCP tools</a> and the <a href="/operate/metrics.html">metrics export</a> show, so a number means the same thing wherever it appears. Days are UTC.</p><p><strong>History</strong> says how far back a metric reaches. <em>Any period</em>: it is read from the daily rollups, which keep their numbers when <a href="/operate/storage.html#data-retention">retention</a> deletes old runs. <em>Stored rows</em>: it is read from the runs, clusters or gaps still stored, so a metric about test identities reaches back only as far as retention keeps runs.</p><h2 id="runs" tabindex="-1">Runs <a class="header-anchor" href="#runs" aria-label="Permalink to &quot;Runs&quot;">​</a></h2><p>Counted over the runs of the period.</p><table tabindex="0"><thead><tr><th>Metric</th><th>Unit</th><th>Better when</th><th>History</th><th>Definition</th></tr></thead><tbody><tr><td><span id="run-success-rate"><strong>Run success rate</strong></span> <code>run-success-rate</code></td><td>percent</td><td>higher</td><td>any period</td><td>Share of finished runs whose status is passed.</td></tr><tr><td><span id="runs"><strong>Runs</strong></span> <code>runs</code></td><td>count</td><td>neither</td><td>any period</td><td>Finished runs in the period.</td></tr><tr><td><span id="suite-size"><strong>Suite size</strong></span> <code>suite-size</code></td><td>count</td><td>neither</td><td>any period</td><td>The highest number of tests a single run of the period reported.</td></tr><tr><td><span id="ci-time"><strong>CI time</strong></span> <code>ci-time</code></td><td>minutes</td><td>lower</td><td>any period</td><td>Sum of the durations of the runs of the period.</td></tr><tr><td><span id="average-run-duration"><strong>Average run duration</strong></span> <code>average-run-duration</code></td><td>milliseconds</td><td>lower</td><td>any period</td><td>Sum of the run durations divided by the number of runs.</td></tr><tr><td><span id="average-p90-test-duration"><strong>Average p90 test duration</strong></span> <code>average-p90-test-duration</code></td><td>milliseconds</td><td>lower</td><td>any period</td><td>Sum of each run’s 90th-percentile test duration divided by the number of runs.</td></tr></tbody></table><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><p>Counted over the tests and executions of the period.</p><table tabindex="0"><thead><tr><th>Metric</th><th>Unit</th><th>Better when</th><th>History</th><th>Definition</th></tr></thead><tbody><tr><td><span id="test-pass-rate"><strong>Test pass rate</strong></span> <code>test-pass-rate</code></td><td>percent</td><td>higher</td><td>any period</td><td>Tests passed divided by tests run, summed over the runs of the period.</td></tr><tr><td><span id="flaky-occurrences"><strong>Flaky occurrences</strong></span> <code>flaky-occurrences</code></td><td>count</td><td>lower</td><td>any period</td><td>Tests that passed only on a retry, summed over the runs of the period.</td></tr><tr><td><span id="flaky-tests"><strong>Flaky tests</strong></span> <code>flaky-tests</code></td><td>count</td><td>lower</td><td>stored rows</td><td>Distinct tests that passed only on a retry at least once in the period.</td></tr><tr><td><span id="wasted-ci-minutes"><strong>Wasted CI minutes</strong></span> <code>wasted-ci-minutes</code></td><td>minutes</td><td>lower</td><td>any period</td><td>Minutes spent inside wait steps plus minutes spent executing attempts that ended failed or timed out.</td></tr><tr><td><span id="wasted-ci-cost"><strong>Wasted CI cost</strong></span> <code>wasted-ci-cost</code></td><td>currency</td><td>lower</td><td>any period</td><td>Wasted CI minutes multiplied by the configured cost of a CI minute; shown only when a cost is set.</td></tr><tr><td><span id="new-regressions"><strong>New regressions</strong></span> <code>new-regressions</code></td><td>count</td><td>lower</td><td>any period</td><td>Executions of a test that failed after passing in its previous run.</td></tr><tr><td><span id="newly-flaky"><strong>Newly flaky</strong></span> <code>newly-flaky</code></td><td>count</td><td>lower</td><td>any period</td><td>Executions of a test that became flaky in that run.</td></tr><tr><td><span id="quarantine-debt"><strong>Quarantine debt</strong></span> <code>quarantine-debt</code></td><td>count</td><td>lower</td><td>stored rows</td><td>Tests in quarantine.</td></tr></tbody></table><h2 id="failure-causes" tabindex="-1">Failure causes <a class="header-anchor" href="#failure-causes" aria-label="Permalink to &quot;Failure causes&quot;">​</a></h2><p>Counted over <a href="/guide/concepts.html#error-fingerprint-failure-cluster">failure clusters</a>, which outlive run retention.</p><table tabindex="0"><thead><tr><th>Metric</th><th>Unit</th><th>Better when</th><th>History</th><th>Definition</th></tr></thead><tbody><tr><td><span id="open-failure-causes"><strong>Open failure causes</strong></span> <code>open-failure-causes</code></td><td>count</td><td>lower</td><td>stored rows</td><td>Failure clusters that are open and not snoozed at the end of the period.</td></tr><tr><td><span id="failure-causes-opened"><strong>Failure causes opened</strong></span> <code>failure-causes-opened</code></td><td>count</td><td>lower</td><td>stored rows</td><td>Failure clusters created inside the period.</td></tr><tr><td><span id="failure-causes-fixed"><strong>Failure causes fixed</strong></span> <code>failure-causes-fixed</code></td><td>count</td><td>higher</td><td>stored rows</td><td>Failure clusters whose fix landed inside the period.</td></tr><tr><td><span id="median-time-to-fix"><strong>Median time to fix</strong></span> <code>median-time-to-fix</code></td><td>days</td><td>lower</td><td>stored rows</td><td>Median time from first failure to fix over the failure clusters fixed in the period.</td></tr><tr><td><span id="oldest-open-failure-cause"><strong>Oldest open failure cause</strong></span> <code>oldest-open-failure-cause</code></td><td>days</td><td>lower</td><td>stored rows</td><td>Age of the oldest open failure cluster.</td></tr><tr><td><span id="fixes-that-held"><strong>Fixes that held</strong></span> <code>fixes-that-held</code></td><td>percent</td><td>higher</td><td>stored rows</td><td>Failure clusters fixed in the period and not regressed since, over the clusters fixed.</td></tr></tbody></table><h2 id="scenario-gaps" tabindex="-1">Scenario gaps <a class="header-anchor" href="#scenario-gaps" aria-label="Permalink to &quot;Scenario gaps&quot;">​</a></h2><p>Counted over the <a href="/features/scenario-gaps.html">Test Map</a>; hidden where the Test Map is declined.</p><table tabindex="0"><thead><tr><th>Metric</th><th>Unit</th><th>Better when</th><th>History</th><th>Definition</th></tr></thead><tbody><tr><td><span id="open-scenario-gaps"><strong>Open scenario gaps</strong></span> <code>open-scenario-gaps</code></td><td>count</td><td>lower</td><td>stored rows</td><td>Open scenario gaps, by class: blind spot, false comfort, fragile.</td></tr><tr><td><span id="gaps-closed"><strong>Gaps closed</strong></span> <code>gaps-closed</code></td><td>count</td><td>higher</td><td>stored rows</td><td>Scenario gaps closed inside the period.</td></tr><tr><td><span id="accepted-but-unwritten"><strong>Accepted but unwritten</strong></span> <code>accepted-but-unwritten</code></td><td>count</td><td>lower</td><td>stored rows</td><td>Gaps accepted more than a week ago whose feature still has no trusted test.</td></tr><tr><td><span id="open-resilience-findings"><strong>Open resilience findings</strong></span> <code>open-resilience-findings</code></td><td>count</td><td>lower</td><td>stored rows</td><td>Open findings from server probes in the unhandled and degraded classes.</td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/features/analytics.html">Analytics</a>: the scope and the comparison period every metric is measured over</li><li><a href="/reference/analytics-widgets.html">Analytics widgets</a>: the widgets that show these metrics</li><li><a href="/operate/metrics.html">Metrics and rollup export</a>: the rollups behind the <em>any period</em> metrics</li></ul>',17)])])}const f=e(a,[["render",n]]);export{p as __pageData,f as default};
